            if (involves(session.development || {}, affected)) fail('관련 성격 변화 기록이 있어 자동 통합을 보류합니다.');
            if (involves(session.rivalries || {}, affected)) fail('관련 경쟁 기록이 있어 자동 통합을 보류합니다.');
