        if (aliases.length > 128) fail('이전 이름 보존 한도를 넘어 통합을 보류합니다.');
        store.identityRedirects[old] = { profileId: to, sourceBundleKey: botKey, aliases };
        for (const redirect of Object.values(store.identityRedirects)) if (redirect.profileId === old) redirect.profileId = to;
        delete store.profiles[old];
