  function uiWorkMode() {
    const value = uiPrefConfig().uiWorkPanel;
    return value === 'screen' || value === 'off' ? value : 'chat';
  }
  function uiWorkAvailable() { return typeof R.setChatPanel === 'function' || typeof R.getRootDocument === 'function'; }

  // 이번 실행에서 본 이 채팅의 가장 최근 판단(변형이 여럿이면 가장 늦게 시작한 것). 초기화·불러오기로 무효가 된 것은 뺀다.
  function uiWorkLiveEntry(scopeKey) {
    let best = null;
    for (const [key, entry] of directorAttempts) {
      if (!key.startsWith(`${scopeKey}::`) || !entry?.attempt) continue;
      if (entry.fence && (backgroundFenceResetInvalidated(entry.fence) || (entry.fence.transferGeneration !== undefined && entry.fence.transferGeneration !== transferGeneration))) continue;
      if (!best || String(entry.attempt.startedAt) > String(best.attempt.startedAt)) best = entry;
    }
    return best;
  }
  // 이번 실행에서 아직 판단을 못 본 채팅: 저장된 마지막 판단을 한 번 읽는다(채팅을 바꿀 때, 초기화·불러오기 뒤에 다시). 최신 확정 응답의 판단만 쓴다.
  function uiWorkStoredAttempt(scopeKey, bundleKey) {
    const stamp = [allResetGeneration, transferGeneration, mapGeneration(scopeResetGenerations, scopeKey), mapGeneration(botResetGenerations, bundleKey)].join(':');
    const cached = uiWork.stored.get(scopeKey);
    if (cached?.stamp === stamp) return cached.attempt;
    if (!uiWork.storedReads.has(scopeKey)) {
      const read = (async () => {
        let attempt = null;
        try {
          const state = await pluginStorageGet(`${SESSION_KEY_PREFIX}${scopeKey}`, null);
          const candidate = isPlainObject(state) ? normalizeDirectorAttempt(state.lastDirectorAttempt) : null;
          if (candidate && candidate.scopeKey === scopeKey && candidate.variantKey === String(state.variantKey || 'default')
            && latestCommitJournalEntry(state)?.commitId === candidate.baseCommitId) attempt = candidate;
        } catch (_) { /* 못 읽으면 표시하지 않는다 */ }
        uiWork.stored.delete(scopeKey);
        uiWork.stored.set(scopeKey, { stamp, attempt });
        if (uiWork.stored.size > 24) uiWork.stored.delete(uiWork.stored.keys().next().value);
      })().finally(() => { uiWork.storedReads.delete(scopeKey); uiWorkSchedule(); });
      uiWork.storedReads.set(scopeKey, read);
    }
    return null;
  }
  // 표시할 상태 하나: hidden · judging · analysis · ready · failed(retry = 한 번 더 예약). 장면 판단 중 > 인물 분석 중 > 끝난 판단의 결과.
  function uiWorkState() {
    const config = configCache;
    if (uiWork.stopped || unloaded || stateRecoveryFault || !config?.enabled || config.mode === 'off' || !uiWork.scopeKey) return { kind: 'hidden' };
    const live = uiWorkLiveEntry(uiWork.scopeKey);
    if (live && !isDirectorTerminal(live.attempt) && backgroundFenceIsCurrent(live.fence)) return { kind: live.attempt.emergency ? 'emergency' : 'judging' };
    if (analysisRuntime.running && (!analysisRuntime.sourceBundleKey || analysisRuntime.sourceBundleKey === uiWork.bundleKey)) return { kind: 'analysis' };
    const attempt = live ? live.attempt : uiWorkStoredAttempt(uiWork.scopeKey, uiWork.bundleKey);
    if (attempt?.phase === 'prepared') return { kind: 'ready' };
    if (attempt?.phase === 'failed') return { kind: 'failed', retry: !!live && judgmentRetryTimers.get(`${attempt.scopeKey}::${attempt.variantKey || 'default'}`)?.attemptId === attempt.id };
    return { kind: 'hidden' };
  }
