      + `<path d="${HOME_HEART_PATH}" fill="none" stroke="${tone.line}"${shade ? ' stroke-opacity=".9"' : ''} stroke-width="1.6"/>`
      + `<path d="${HOME_INNER_PATH}" fill="none" stroke="${tone.inner}" stroke-width="2.6"${shade ? ' stroke-linejoin="round"' : ''}/>`;
