    const fertility = !active ? 'unavailable' : hormonal ? 'none' : irregular || transition || anovulatory ? 'unavailable' : day >= ovulation - 5 && day <= ovulation + 1 ? 'higher' : 'lower';
    // 날짜 곡선(몸): 월경 전 7~4일은 0.7, 3~1일은 그대로. 주기마다 곡선 시작이 하루 앞뒤로, 몸 세기가 ±15% 흔들린다(평탄한 피임 제외).
