    if (active && value.symptoms && value.symptomToken === token) Object.assign(symptoms, value.symptoms);
    // 이번 주기와 지난 주기의 시작(이야기 시간 분). 관계 기록은 지난 월경 뒤의 것만 본다.
    const cycleStartMinute = active ? value.anchorMinute + (startOrdinal - (initialDay - 1)) * 1440 : null;
