      if (!isPlainObject(patch)) continue;
      const actor = resolveEntity(registry, patch.actor, state.scopeKey);
      const target = resolveEntity(registry, patch.target, state.scopeKey) || (String(patch.target || '').trim().toLowerCase() === 'user' ? 'user' : null);
      if (!actor || actor === 'user' || !target || actor === target || !actorAllowed(actor) || !actorAllowed(target)) continue;
      if (!profileStore.profiles?.[actor] || !isProfileDirectorEligible(profileStore.profiles[actor])) continue;
      if (target !== 'user' && profileStore.profiles?.[target] && !isProfileDirectorEligible(profileStore.profiles[target])) continue;
