    const pending = { scope, epoch, lifecycleEpoch: requestLifecycleEpoch, backgroundFence, lookaheadConversation: conversation,
      lookaheadExternalContext: externalContext, externalSources };
    const base = { commitId: baseCommit.commitId, contentHash: baseCommit.contentHash, turnIndex: state.turnIndex, state, registry, profileStore, botOverride,
      epoch, lifecycleEpoch: requestLifecycleEpoch, backgroundFence, profileSourceIds, planOnly: true, emergency, lookaheadEligible: true };
