    if (base.userIdentity?.signature && base.userIdentity.signature !== scope.userIdentity?.signature) return no('RECOVERY_PERSONA_CHANGED');
    if (base.directorObservationApplied === true || state.preparedLookahead?.baseCommitId === base.commitId) return no('RECOVERY_OBSERVED');
    if (base.directorObservationApplied !== false || !base.undo?.hasBaseline || base.unverified || !attempt || attempt.applied
      || attempt.baseCommitId !== base.commitId || attempt.scopeKey !== scope.scopeKey || attempt.variantKey !== scope.variantKey) return no('RECOVERY_UNVERIFIABLE');
    if (!recoveryChatMatches(scope, state)) return no('RECOVERY_CHAT_CHANGED');
