    if (directorAttempts.has(partition) || [...decisionPromises.keys()].some(key => key.startsWith(`${scope.scopeKey}:`))) return no('RECOVERY_LIVE_TASK');
    if (state.sceneRecovery?.baseCommitId === base.commitId && state.sceneRecovery?.baseContentHash === base.contentHash) return no('RECOVERY_ALREADY_TRIED');
    if (isDirectorTerminal(attempt)) return no('RECOVERY_TERMINAL');
