  function uiRefreshSheet(context) {
    const state = uiSheetState;
    if (!state || !state.sheet.isConnected || state.spec.static) return;
    const top = state.body.scrollTop;
    const open = Object.fromEntries([...state.body.querySelectorAll('details')].map((node, index) => [uiDetailsKey(node, index), node.open]));
    state.body.replaceChildren();
    try { state.spec.build(state.body, context); } catch (error) { uiAppend(state.body, 'p', String(error?.message || error), 'es-warning'); }
    [...state.body.querySelectorAll('details')].forEach((node, index) => { const key = uiDetailsKey(node, index); if (Object.hasOwn(open, key)) node.open = open[key]; });
    state.body.scrollTop = top;
  }
  function uiCloseSheet(immediate = false) {
    const state = uiSheetState;
    if (!state) return;
    uiSheetState = null;
    state.spec.onClose?.();
    if (immediate || !esFx.on()) { state.veil.remove(); state.sheet.remove(); return; }
    state.veil.classList.remove('show');
    state.sheet.classList.remove('open');
    setTimeout(() => { state.veil.remove(); state.sheet.remove(); }, 340);
  }

  function renderRelationMultiplierSettings(parent, context) {
    if (!context.botOverride || !context.scope?.sourceBundleKey) return;
    const scope = { ...context.scope };
    const panel = uiAppend(parent, 'section', '', 'es-panel');
    uiAppend(panel, 'h3', '현재 봇의 관계 변화 배수');
    uiAppend(panel, 'p', '이후 대화에서 호감·끌림·증오가 증가하거나 감소하는 양을 조절합니다. 기본 1.0배, 0.0배는 새 수치 변화 정지입니다. 기존 값·과거 기록·프로필 분석에는 소급 적용하지 않습니다.', 'es-muted');
    const grid = uiAppend(panel, 'div', '', 'es-form-grid');
    const rates = normalizeRelationChangeMultipliers(context.botOverride.relationChangeMultipliers);
    for (const [field, label] of [['affection', '호감 변화 배수'], ['eroticAttraction', '끌림 변화 배수'], ['hatred', '증오 변화 배수']]) {
      let committed = rates[field], busy = false;
      const input = createInputField(grid, label, committed.toFixed(1), { type: 'number', min: 0, max: 3, step: 0.1 });
      input.setAttribute('aria-label', label);
      input.addEventListener('change', async () => {
        if (busy) { input.value = committed.toFixed(1); return; }
        const value = parseRelationChangeMultiplier(input.value);
        if (value === null) {
          input.value = committed.toFixed(1);
          setUiStatus('관계 배수는 0.0~3.0 사이에서 0.1 단위로 입력해 주세요. 기존 설정을 유지했습니다.', 'warn');
          return;
        }
        busy = true; input.disabled = true;
        try {
          committed = await saveRelationChangeMultiplier(scope, field, value);
          input.value = committed.toFixed(1);
          setUiStatus(`${label} ${committed.toFixed(1)}배를 저장했습니다. 이후 관계 변화에 적용됩니다.`, 'ok');
        } catch (error) {
          input.value = committed.toFixed(1);
          setUiStatus(`관계 배수 저장 실패: ${error?.message || error}`, 'error');
        } finally {
          busy = false;
          if (input.isConnected) input.disabled = false;
        }
      });
    }
  }





