  function createButton(parent, label, className, onClick, options = {}) {
    const button = uiAppend(parent, 'button', label, `es-button ${className || 'secondary'}`.trim());
    button.type = 'button';
    button.disabled = options.disabled === true;
    if (options.title) button.title = options.title;
    let busy = false;
    button.addEventListener('click', (event) => {
      if (busy || button.disabled || (transferBusy && options.transferAllowed !== true)) return;
      busy = true;
      button.disabled = true;
      Promise.resolve(onClick?.(event))
        .catch((error) => setUiStatus(error?.message || error, 'error'))
        .finally(() => {
          busy = false;
          if (button.isConnected) button.disabled = options.disabled === true;
        });
    });
    return button;
  }

