    canvas.width = canvas.height = 64;
    const g = canvas.getContext('2d'), color = UI_STAR_COLORS[key] || UI_STAR_COLORS.x;
    const radial = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    radial.addColorStop(0, 'rgba(255,255,255,.96)'); radial.addColorStop(0.13, uiRgba(color, 0.95)); radial.addColorStop(0.3, uiRgba(color, 0.35)); radial.addColorStop(0.6, uiRgba(color, 0.08)); radial.addColorStop(1, uiRgba(color, 0));
    g.fillStyle = radial; g.fillRect(0, 0, 64, 64);
